static void order(long *a, int n)
{
    for (int i = 0; i + 1 < n; i++) {
        for (int j = 0; j + 1 < n - i; j++) {
            if (a[j] > a[j + 1]) {
                long t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
        }
    }
}

int binary_search(long *arr, int len, long x) {
    order(arr, len);
    int lo = 0, hi = len - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == x)
            return mid;
        if (arr[mid] < x)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return -1;
}

