static void isort(long *a, int n)
{
    for (int i = 0; i + 1 < n; i++) {
        for (int j = 0; j + 1 < n - i; j++) {
            if (a[j] > a[j + 1]) {
                long t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
        }
    }
}

int lower_bound_x(long *v, int n, long target)
{
    isort(v, n);
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] < target)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

