        return 0;
    int even = 0;
    long am = 0;
    int neg = 0;
    long mn = vals[0];
    for (int i = 0; i < len; i++) {
        if (vals[i] % 2 == 0)
            even++;
        long av = vals[i] < 0 ? -(long)vals[i] : vals[i];
        if (av > am)
            am = av;
        neg += vals[i] < 0;
        if (vals[i] < mn)
            mn = vals[i];
    }
    return neg - mn - even + am;
}

