 uni1=uni+1;
 uni2=uni-1;

 if((uni^uni1)&(~7))uni1=uni;
 if((uni^uni2)&(~7))uni2=uni;

 if(lsbit)
 {
  if(lsbit==4)
  {
   uni&=~1;
   uni1&=~1;
   uni2&=~1;

   uni|=(uni>>1)&(uni>>2)&1;
   uni1|=(uni1>>1)&(uni1>>2)&1;
   uni2|=(uni2>>1)&(uni2>>2)&1;
  }else if(lsbit&1)
   { uni|=1; uni1|=1; uni2|=1; }
