 d3=tgt2-p1; d3=d3^(d3>>31); d1+=d3>>5;
 d3=tgt2-p2; d3=d3^(d3>>31); d2+=d3>>5;

 if(d1<d0)uni=uni1;
 if(d2<d0)uni=uni2;

 return(uni);
}

