int binomial_coefficient(int n, int k) {

  int cur_n;
  int cur_k;
  int val = 1;
  int prev_val = 1;
  int lim1 = k;
  int lim2 = n - k;
  if(k > n) {
    return 0;
  }

  if(lim1 < lim2) {
    int temp = lim1;
    lim1 = lim2;
    lim2 = temp;
  }

  cur_k = 2;

  for(cur_n = lim1+1; cur_n <= n ; cur_n ++) {
    prev_val = val;
    val = val * cur_n;
    if(val / cur_n != prev_val) {
      return -1;
    }

    while(cur_k <= lim2 && val % cur_k == 0) {
      val = val / cur_k;
      cur_k ++;
    }
  }

  return val;
}

