    high = n - 1;
    while(low < high) {
        mid = (low + high) / 2;
        if (x > v[mid]) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    if (v[low] == x) {
        return low;
    } else {
        return -1;
    }
}

